import numpy as np


class CfgBanditEpsJADEv4:
    """Epsilon-constrained JADE with a per-discrete-configuration feasible archive.
    Earlier switch to feasibility-first, a UCB bandit over the top discrete
    configurations (reward = relative improvement), exhaustive single-discrete-change
    sweeps, adaptive pattern search over continuous variables, Cauchy perturbations of
    the incumbent, and a small reserved final intensification phase (5% of budget)."""

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        rng = np.random.default_rng()
        lb = np.asarray(func.bounds.lb, dtype=float).copy()
        ub = np.asarray(func.bounds.ub, dtype=float).copy()
        d = lb.size
        vt = [str(t) for t in func.variable_types]
        is_disc = np.array([t != "continuous" for t in vt], dtype=bool)
        is_cat = np.array([t in ("categorical", "binary") for t in vt], dtype=bool)
        disc = np.where(is_disc)[0]
        cont = np.where(~is_disc)[0]
        nv = np.ones(d, dtype=int)
        for j in disc:
            nv[j] = max(1, int(round(float(func.n_values[j]))))
        span = ub - lb
        budget = self.budget
        final_start = int(0.95 * budget)

        self.n_used = 0
        self.best_f = np.inf
        self.best_x = None
        cache = {}
        cfg_best = {}   # discrete configuration -> (f, x), best feasible
        cfg_stat = {}   # discrete configuration -> [pulls, reward sum]

        def repair(x):
            x = np.clip(np.asarray(x, dtype=float), lb, ub)
            if disc.size:
                x[disc] = np.clip(np.rint(x[disc]), 0, nv[disc] - 1)
            return x

        def left():
            return budget - self.n_used

        def de_ok():
            return self.n_used < final_start and left() > 0

        def cfg_key(x):
            return tuple(int(round(x[j])) for j in disc)

        def ev(x):
            x = repair(x)
            k = x.tobytes()
            if k in cache:
                f, v = cache[k]
                return f, v, x.copy()
            f, g = func(x.copy())
            self.n_used += 1
            g = np.nan_to_num(np.asarray(g, dtype=float).ravel(), nan=1e6, posinf=1e6)
            v = float(np.sum(np.maximum(g, 0.0)))
            f = float(f)
            if not np.isfinite(f):
                f = np.inf
                v = max(v, 1e6)
            cache[k] = (f, v)
            if v <= 0:
                if f < self.best_f:
                    self.best_f = f
                    self.best_x = x.copy()
                ck = cfg_key(x)
                if ck not in cfg_best or f < cfg_best[ck][0]:
                    cfg_best[ck] = (f, x.copy())
            return f, v, x.copy()

        def better(f1, v1, f2, v2):
            if v1 <= 0 and v2 <= 0:
                return f1 < f2
            if v1 <= 0:
                return True
            if v2 <= 0:
                return False
            return v1 < v2

        def better_eps(f1, v1, f2, v2, eps):
            a = v1 <= eps
            b = v2 <= eps
            if a and b:
                return f1 < f2
            if a:
                return True
            if b:
                return False
            return v1 < v2

        def ranking(F, V, eps):
            cls = (V > eps).astype(int)
            val = np.where(cls == 0, F, V)
            return np.lexsort((val, cls))

        def lhs(n):
            if n <= 0:
                return []
            U = np.empty((n, d))
            for j in range(d):
                U[:, j] = (rng.permutation(n) + rng.random(n)) / n
            X = lb + U * span
            if disc.size:
                X[:, disc] = np.floor(U[:, disc] * nv[disc])
            return [repair(x) for x in X]

        def disc_sweep(x0, f0, max_ev):
            """Evaluate every single discrete-value change around x0; return best feasible."""
            x, f = x0.copy(), f0
            n0 = self.n_used
            for j in disc:
                for t in range(nv[j]):
                    if self.n_used - n0 >= max_ev or left() <= 0:
                        return x, f
                    if t == int(round(x[j])):
                        continue
                    y = x.copy()
                    y[j] = t
                    fy, vy, yr = ev(y)
                    if vy <= 0 and fy < f:
                        x, f = yr, fy
            return x, f

        def cont_search(x0, f0, v0, max_ev, step0=0.05):
            """Adaptive pattern search over continuous variables with discrete neighbour moves."""
            x, f, v = x0.copy(), f0, v0
            n0 = self.n_used

            def room():
                return (self.n_used - n0) < max_ev and left() > 0

            step = step0
            while room() and step > 1e-3:
                improved = False
                x_prev = x.copy()
                for j in cont:
                    for s in (1.0, -1.0):
                        if not room():
                            break
                        y = x.copy()
                        y[j] += s * step * span[j]
                        fy, vy, yr = ev(y)
                        if better(fy, vy, f, v):
                            x, f, v = yr, fy, vy
                            improved = True
                            break
                for j in disc:
                    for s in (1, -1):
                        if not room():
                            break
                        t = int(round(x[j])) + s
                        if t < 0 or t >= nv[j]:
                            continue
                        y = x.copy()
                        y[j] = t
                        fy, vy, yr = ev(y)
                        if better(fy, vy, f, v):
                            x, f, v = yr, fy, vy
                            improved = True
                            break
                if improved and room():
                    z = repair(x + (x - x_prev))
                    fz, vz, zr = ev(z)
                    if better(fz, vz, f, v):
                        x, f, v = zr, fz, vz
                    step = min(step * 1.6, 0.3)
                else:
                    step *= 0.5
            return x, f, v

        def local_stage(ls_budget):
            """UCB bandit over top discrete configurations; reward = relative improvement."""
            if not cfg_best or ls_budget <= 0:
                return
            items = sorted(cfg_best.items(), key=lambda kv: kv[1][0])[:4]
            spent = 0
            chunk = max(4, ls_budget // 3)
            while spent < ls_budget and left() > 0:
                total = sum(cfg_stat.get(ck, [0, 0.0])[0] for ck, _ in items) + 1
                best_score, pick = -np.inf, None
                for ck, _ in items:
                    p, r = cfg_stat.get(ck, [0, 0.0])
                    mean = r / p if p > 0 else 0.0
                    sc = mean + 0.5 * np.sqrt(np.log(total + 1.0) / (p + 1.0))
                    if sc > best_score:
                        best_score, pick = sc, ck
                if pick is None:
                    break
                f0, x0 = cfg_best[pick]
                before = self.n_used
                budget_here = min(chunk, ls_budget - spent, left())
                x1, f1 = disc_sweep(x0, f0, max(1, budget_here // 3))
                _, f1, _ = cont_search(x1, f1, 0.0, max(1, budget_here - (self.n_used - before)), 0.1)
                used = self.n_used - before
                if used <= 0:
                    break
                spent += used
                rew = 0.0
                if f1 < f0:
                    rew = min(1.0, (f0 - f1) / (abs(f0) + 1e-9))
                st = cfg_stat.setdefault(pick, [0, 0.0])
                st[0] += 1
                st[1] += rew

        def sample_F(mu):
            for _ in range(20):
                f = mu + 0.1 * np.tan(np.pi * (rng.random() - 0.5))
                if f > 0:
                    return min(f, 1.0)
            return 0.5

        def sample_CR(mu):
            return float(np.clip(rng.normal(mu, 0.1), 0.0, 1.0))

        NP = int(np.clip(3 * d + 10, 12, 60))
        X_list, F_list, V_list = [], [], []
        for x in lhs(min(NP, budget)):
            if left() <= 0:
                break
            f, v, xr = ev(x)
            X_list.append(xr)
            F_list.append(f)
            V_list.append(v)
        if len(X_list) == 0:
            return self.best_f, self.best_x

        X = np.array(X_list)
        F = np.array(F_list, dtype=float)
        V = np.array(V_list, dtype=float)
        n = len(X)

        fin_v = V[(V < 1e5)]
        eps0 = float(min(np.median(fin_v), 1e3)) if fin_v.size else 0.0
        eps = eps0
        Tc = 0.4 * budget
        cp = 5.0

        def eps_sched():
            return eps0 * (1.0 - min(1.0, self.n_used / Tc)) ** cp

        mu_F, mu_CR = 0.5, 0.8
        archive = []
        stall = 0
        empty_gens = 0
        stall_limit = 5 + d
        last = self.best_f
        n_disc_vals = int(np.sum(nv[disc])) if disc.size else 0
        elite_k = max(2, NP // 5)
        radius = 0.3

        def restart(improved_recently):
            nonlocal X, F, V, archive, radius
            if improved_recently:
                radius = 0.3
            else:
                radius = max(0.005, radius * 0.6)
            order = ranking(F, V, 0.0)
            seeds = [X[i].copy() for i in order[:elite_k]]
            seedF = [F[i] for i in order[:elite_k]]
            seedV = [V[i] for i in order[:elite_k]]
            if self.best_x is not None:
                seeds = [self.best_x.copy()] + seeds
                seedF = [self.best_f] + seedF
                seedV = [0.0] + seedV
            m = NP - len(seeds)
            new_X, new_F, new_V = list(seeds), list(seedF), list(seedV)
            pts = []
            if self.best_x is not None:
                others = [v[1] for v in cfg_best.values()]
                for _ in range(max(0, m)):
                    u = rng.random()
                    if u < 0.6 or len(others) <= 1:
                        base = self.best_x
                        r = radius * rng.choice([0.3, 1.0, 3.0])
                    elif u < 0.85:
                        base = others[rng.integers(len(others))]
                        r = radius * rng.choice([1.0, 3.0])
                    else:
                        pts.append(lhs(1)[0])
                        continue
                    y = base.copy()
                    if cont.size:
                        mask = rng.random(cont.size) < 0.7
                        y[cont] += mask * rng.uniform(-r, r, cont.size) * span[cont]
                    for j in disc:
                        if rng.random() < min(0.5, 0.2 * radius / 0.3 + 0.05):
                            if is_cat[j]:
                                y[j] = rng.integers(nv[j])
                            else:
                                y[j] = y[j] + rng.choice([-1, 1])
                    pts.append(repair(y))
            else:
                pts = lhs(m)
            for y in pts:
                if not de_ok():
                    break
                f, v, yr = ev(y)
                new_X.append(yr)
                new_F.append(f)
                new_V.append(v)
            if len(new_X) == 0:
                return False
            X = np.array(new_X)
            F = np.array(new_F, dtype=float)
            V = np.array(new_V, dtype=float)
            archive = []
            return True

        while de_ok():
            n = len(X)
            base_eps = eps_sched()
            feas_ratio = float(np.mean(V <= eps)) if n else 0.0
            if feas_ratio > 0.5:
                eps = min(eps, base_eps) * 0.95
            else:
                eps = max(base_eps, eps * 0.99)
            eps = min(eps, eps0)
            if self.n_used >= Tc:
                eps = 0.0
            order = ranking(F, V, eps)
            top = order[:max(2, int(0.15 * n))]
            evals_before = self.n_used
            SF, SCR = [], []

            for i in range(n):
                if not de_ok():
                    break
                Fi = sample_F(mu_F)
                CRi = sample_CR(mu_CR)

                # occasional Cauchy-perturbed incumbent trial (feasibility-aware exploitation)
                if self.best_x is not None and cont.size and rng.random() < 0.05:
                    y = self.best_x.copy()
                    y[cont] += 0.02 * np.tan(np.pi * (rng.random(cont.size) - 0.5)) * span[cont]
                    fy, vy, yr = ev(np.clip(y, lb, ub))
                    if better_eps(fy, vy, F[i], V[i], eps):
                        archive.append(X[i].copy())
                        if len(archive) > NP:
                            archive.pop(rng.integers(len(archive)))
                        X[i], F[i], V[i] = yr, fy, vy
                    continue

                pb = X[rng.choice(top)]
                pool_n = n + len(archive)
                if pool_n >= 3:
                    others_idx = np.delete(np.arange(n), i)
                    r1 = rng.choice(others_idx)
                    r2_idx = rng.integers(pool_n - 1)
                    if r2_idx < n - 1:
                        cand = np.delete(np.arange(n), [i, r1])
                        r2_vec = X[rng.choice(cand)] if cand.size else X[i]
                    else:
                        r2_vec = archive[rng.integers(len(archive))]
                    xr1 = X[r1]
                else:
                    xr1 = X[i]
                    r2_vec = X[i]
                mut = X[i] + Fi * (pb - X[i]) + Fi * (xr1 - r2_vec)
                cross = rng.random(d) < CRi
                cross[rng.integers(d)] = True
                tr = np.where(cross, mut, X[i])
                for j in disc:
                    if rng.random() < 0.08:
                        if is_cat[j]:
                            tr[j] = rng.integers(nv[j])
                        else:
                            tr[j] = np.rint(tr[j]) + rng.choice([-1, 1])
                f, v, xr = ev(tr)
                if better_eps(f, v, F[i], V[i], eps):
                    archive.append(X[i].copy())
                    if len(archive) > NP:
                        archive.pop(rng.integers(len(archive)))
                    SF.append(Fi)
                    SCR.append(CRi)
                    X[i], F[i], V[i] = xr, f, v

            # feasibility bisection towards the incumbent
            if self.best_x is not None and de_ok():
                infeas = np.where(V > 0)[0]
                if infeas.size:
                    for i in rng.choice(infeas, min(2, infeas.size), replace=False):
                        if not de_ok():
                            break
                        t = rng.uniform(0.3, 0.7)
                        y = self.best_x + t * (X[i] - self.best_x)
                        f, v, yr = ev(y)
                        if better_eps(f, v, F[i], V[i], eps):
                            X[i], F[i], V[i] = yr, f, v

            if SF:
                sf = np.asarray(SF)
                mu_F = 0.9 * mu_F + 0.1 * (np.sum(sf ** 2) / max(np.sum(sf), 1e-12))
                mu_CR = 0.9 * mu_CR + 0.1 * float(np.mean(SCR))

            if self.n_used == evals_before:
                empty_gens += 1
            else:
                empty_gens = 0

            improved_recently = self.best_f < last - 1e-12
            if improved_recently:
                stall = 0
                last = self.best_f
            else:
                stall += 1

            if (stall >= stall_limit or empty_gens >= 3) and de_ok():
                ls_budget = min(left() - (budget - final_start) if left() > budget - final_start else 0,
                                6 * d + 3 * n_disc_vals + 10)
                ls_budget = max(ls_budget, min(left(), 6 * d + 3 * n_disc_vals + 10))
                local_stage(ls_budget)
                if not restart(improved_recently):
                    break
                stall = 0
                empty_gens = 0
                last = self.best_f

        # final intensification on the incumbent with the reserved budget
        if self.best_x is not None and left() > 0:
            x1, f1 = disc_sweep(self.best_x, self.best_f, max(1, left() // 4))
            cont_search(x1, f1, 0.0, left(), 0.02)
            stagn = 0
            while left() > 0:
                prev = self.best_f
                r = 0.01 * (0.5 ** (stagn // 5))
                y = self.best_x.copy()
                if cont.size:
                    y[cont] += rng.normal(0.0, r, cont.size) * span[cont]
                for j in disc:
                    if rng.random() < 0.1:
                        y[j] = rng.integers(nv[j]) if is_cat[j] else y[j] + rng.choice([-1, 1])
                ev(y)
                stagn = 0 if self.best_f < prev - 1e-12 else stagn + 1
        else:
            while left() > 0:
                pts = lhs(min(left(), 50))
                if not pts:
                    break
                for y in pts:
                    if left() <= 0:
                        break
                    ev(y)

        return self.best_f, self.best_x
